FROM vault_owner_record_head h JOIN vault_owner_key_head root ON root.account_id=h.account_id AND root.vault_id=h.vault_id  JOIN sso_context sx ON sx.secret_hash=?12 JOIN sso_session ss ON ss.sso_id=sx.sso_id AND ss.account_id=h.account_id  JOIN account_security a ON a.account_id=ss.account_id JOIN credential c ON c.account_id=ss.account_id AND c.credential_id=ss.credential_id  JOIN vault_owner_key_wrap w ON w.account_id=root.account_id AND w.key_generation=root.key_generation AND w.credential_id=ss.credential_id  WHERE h.account_id=?1 AND root.origin=?2 AND h.vault_id=?3 AND h.collection_id=?4 AND h.record_id=?5 AND h.kind=?6  AND h.revision=?7 AND h.ciphertext_sha256=?8 AND h.key_generation=?9 AND root.key_generation=?9 AND root.revision=?10  AND h.deleted=0 AND h.format_version=2 AND root.format_version=2 AND root.suite='PRF-HKDF-SHA256-AES256GCM-v2'  AND ss.revoked=0 AND ss.expires_at>unixepoch() AND ss.credential_id=?11 AND a.active=1 AND a.epoch=ss.epoch AND c.active=1
